{"filename": "test_sorted_intersection.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
sorted_intersection = target.sorted_intersection


def test_basic_intersection():
    # Shared elements 2, 3; output sorted ascending
    assert sorted_intersection([1, 2, 3], [2, 3, 4]) == [2, 3]


def test_duplicates_in_left_are_collapsed():
    # Spec: each shared integer once, regardless of duplicate appearances in either input
    assert sorted_intersection([1, 1, 2], [1, 2]) == [1, 2]


def test_duplicates_in_right_are_collapsed():
    # Spec: each shared integer once, regardless of duplicate appearances in either input
    assert sorted_intersection([1, 2], [1, 1, 2]) == [1, 2]


def test_duplicates_in_both_collapsed():
    # Spec: each shared integer once even if duplicated in both
    assert sorted_intersection([1, 1, 2, 2], [1, 1, 2, 2]) == [1, 2]


def test_empty_left():
    assert sorted_intersection([], [1, 2, 3]) == []


def test_empty_right():
    assert sorted_intersection([1, 2, 3], []) == []


def test_both_empty():
    assert sorted_intersection([], []) == []


def test_no_common_elements():
    assert sorted_intersection([1, 2], [3, 4]) == []


def test_output_sorted_ascending():
    # Inputs unsorted; output must be sorted ascending
    assert sorted_intersection([3, 1, 2], [2, 3, 1]) == [1, 2, 3]


def test_single_shared_element():
    assert sorted_intersection([5], [5]) == [5]


def test_negative_numbers():
    assert sorted_intersection([-1, 0, 1], [0, 1, 2]) == [0, 1]


def test_zero_and_mixed_duplicates():
    # 0 appears 3x in left, 2x in right -> once in output; 7 once each
    assert sorted_intersection([0, 0, 0, 7], [0, 0, 7]) == [0, 7]
"}

